from collections import defaultdict

def main():
    N, M = map(int, input().split())

    # Generate all possible train departure events
    events = []  # (departure_time, from_station, to_station, arrival_time)

    for _ in range(M):
        l, d, k, c, a, b = map(int, input().split())
        curr_time = l
        for _ in range(k):
            events.append((curr_time, a, b, curr_time + c))
            curr_time += d

    # Group events by source station
    train_from = defaultdict(list)
    for dep_time, from_st, to_st, arr_time in events:
        train_from[from_st].append((dep_time, arr_time))

    # f[i] = latest time we can arrive at station N from station i
    f = [-float('inf')] * (N + 1)
    f[N] = 0  # We are already at station N

    # Iterative relaxation until no changes
    max_iterations = 10 * N
    changed = True

    for _ in range(max_iterations):
        changed = False
        # Process stations in reverse order (from N down to 1)
        for station in range(N, 0, -1):
            if f[station] == -float('inf'):
                continue

            # Try all trains departing from this station
            for dep_time, arr_time in train_from[station]:
                # We can take this train if we can depart from 'station' at time <= dep_time
                if f[station] <= dep_time:
                    # We can arrive at 'to_station' at time 'arr_time'
                    # This arrival time can improve our f[to_station] value
                    if arr_time > f[to_station]:
                        f[to_station] = arr_time
                        changed = True

    # Output results for stations 1 to N-1
    for i in range(1, N):
        if f[i] == -float('inf'):
            print("Unreachable")
        else:
            print(f[i])

if __name__ == "__main__":
